-- Study Tracker schema. Run in Supabase SQL Editor before first use.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.syllabus_subjects (id text primary key, name text not null, subject_code text not null, session text not null default '2026-27', source_url text, verified_at date, created_at timestamptz not null default now());
create table if not exists public.syllabus_chapters (id text primary key, subject_id text not null references public.syllabus_subjects(id) on delete cascade, unit_name text not null, chapter_name text not null, topic_name text, source_status text not null default 'provisional' check(source_status in ('verified','provisional','user-added')), source_url text, sort_order int not null default 0);
create table if not exists public.chapter_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, syllabus_item_id text not null, status text not null default 'Not started' check(status in ('Not started','Learning','Needs revision','Practised','Completed')), confidence smallint not null default 3 check(confidence between 1 and 5), notes text, bookmarked boolean not null default false, updated_at timestamptz not null default now(), unique(user_id,syllabus_item_id));
create table if not exists public.daily_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan_date date not null, generated_by text not null default 'ai', total_minutes int not null default 0, created_at timestamptz not null default now(), unique(user_id,plan_date,created_at));
create table if not exists public.daily_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan_id uuid references public.daily_plans(id) on delete set null, title text not null, subject text not null, chapter text not null, objective text, description text, estimated_minutes int not null default 25 check(estimated_minutes between 1 and 360), actual_minutes int check(actual_minutes between 0 and 1440), difficulty text check(difficulty in ('Easy','Medium','Hard')), task_type text not null default 'Revision', reason text, completed boolean not null default false, task_date date not null default current_date, completed_at timestamptz, notes text, sort_order int not null default 0, created_at timestamptz not null default now());
create table if not exists public.notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, content text not null, subject text, chapter text, tags text[] not null default '{}', bookmarked boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.bookmarks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, item_type text not null, item_id text not null, label text, created_at timestamptz not null default now(), unique(user_id,item_type,item_id));
create table if not exists public.quizzes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject text not null, chapter text not null, difficulty text not null, question_set jsonb not null default '[]', source_classification text not null default 'AI-generated practice', created_at timestamptz not null default now());
create table if not exists public.quiz_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, quiz_id uuid references public.quizzes(id) on delete set null, subject text not null, chapter text, score int not null check(score>=0), total_questions int not null check(total_questions>0), difficulty text, mode text not null default 'practice', time_taken_seconds int not null default 0 check(time_taken_seconds>=0), attempted_at timestamptz not null default now());
create table if not exists public.quiz_answers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, attempt_id uuid not null references public.quiz_attempts(id) on delete cascade, question_text text not null, options jsonb not null, selected_index smallint check(selected_index between 0 and 3), correct_index smallint not null check(correct_index between 0 and 3), explanation text, topic text, difficulty text, created_at timestamptz not null default now());
create table if not exists public.revision_schedule (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, syllabus_item_id text not null, due_date date not null, interval_days int not null default 1 check(interval_days>0), reason text not null, last_reviewed_at timestamptz, resolved boolean not null default false, updated_at timestamptz not null default now(), unique(user_id,syllabus_item_id));
create table if not exists public.study_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject text, chapter text, started_at timestamptz not null default now(), ended_at timestamptz, duration_seconds int check(duration_seconds>=0), notes text);
create table if not exists public.user_settings (user_id uuid primary key references auth.users(id) on delete cascade, dark_mode boolean not null default false, accent_color text not null default '#635bff', daily_minutes int not null default 120 check(daily_minutes between 15 and 360), exam_date date not null default '2027-02-15', notification_enabled boolean not null default false, quiet_start time, quiet_end time, timezone text not null default 'Asia/Kolkata', font_size text not null default 'normal', compact_layout boolean not null default false, updated_at timestamptz not null default now());
create table if not exists public.achievements (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, achievement_key text not null, achieved_at timestamptz not null default now(), metadata jsonb not null default '{}', unique(user_id,achievement_key));
create table if not exists public.reminders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, body text, remind_at timestamptz not null, reminder_type text not null default 'study', completed boolean not null default false, created_at timestamptz not null default now());
create index if not exists chapter_progress_user_idx on public.chapter_progress(user_id);
create index if not exists daily_tasks_user_date_idx on public.daily_tasks(user_id,task_date);
create index if not exists notes_user_updated_idx on public.notes(user_id,updated_at desc);
create index if not exists quiz_attempts_user_date_idx on public.quiz_attempts(user_id,attempted_at desc);
create index if not exists revision_due_idx on public.revision_schedule(user_id,due_date) where not resolved;
-- Enable owner-only RLS for every user-owned table.
do $$ declare t text; begin foreach t in array array['chapter_progress','daily_plans','daily_tasks','notes','bookmarks','quizzes','quiz_attempts','quiz_answers','revision_schedule','study_sessions','user_settings','achievements','reminders'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists owner_all on public.%I',t); execute format('create policy owner_all on public.%I for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid())',t); end loop; end $$;
-- profiles uses id instead of user_id
 drop policy if exists profile_owner on public.profiles;
 create policy profile_owner on public.profiles for all to authenticated using (id=auth.uid()) with check (id=auth.uid());
-- Syllabus catalogue is readable by authenticated students and write-protected from clients.
alter table public.syllabus_subjects enable row level security; alter table public.syllabus_chapters enable row level security;
drop policy if exists syllabus_read on public.syllabus_subjects; create policy syllabus_read on public.syllabus_subjects for select to authenticated using (true);
drop policy if exists chapters_read on public.syllabus_chapters; create policy chapters_read on public.syllabus_chapters for select to authenticated using (true);
-- Create a profile automatically after registration.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; insert into public.user_settings(user_id) values(new.id) on conflict(user_id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
